import {
  createContext,
  forwardRef,
  type HTMLAttributes,
  type ButtonHTMLAttributes,
  type ReactNode,
  type Ref,
  type RefObject,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from 'react'
import { createPortal } from 'react-dom'

export type DialogOpenChangeReason =
  | 'close-button'
  | 'escape-key'
  | 'pointer-outside'
  | 'trigger'

export type DialogOpenChangeDetails = {
  reason: DialogOpenChangeReason
  originalEvent?: Event
}

export type DialogRootProps = {
  children: ReactNode
  defaultOpen?: boolean
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void
  open?: boolean
}

type DialogContextValue = {
  contentId: string
  contentRef: RefObject<HTMLDivElement | null>
  descriptionId: string
  descriptionLabelIds: string | undefined
  open: boolean
  registerDescription: (id: string) => () => void
  registerTitle: (id: string) => () => void
  requestOpenChange: (
    open: boolean,
    reason: DialogOpenChangeReason,
    originalEvent?: Event,
  ) => void
  titleLabelId: string | undefined
  titleId: string
  triggerRef: RefObject<HTMLButtonElement | null>
}

const DialogContext = createContext<DialogContextValue | null>(null)
const PortalContext = createContext<HTMLElement | null>(null)

function useDialogContext(component: string) {
  const context = useContext(DialogContext)

  if (!context) {
    throw new Error(`${component} must be rendered inside DialogRoot.`)
  }

  return context
}

function setRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === 'function') {
    ref(value)
  } else if (ref) {
    ref.current = value
  }
}

function useLatest<T>(value: T) {
  const ref = useRef(value)
  ref.current = value
  return ref
}

type InertState = {
  ariaHidden: string | null
  inert: boolean
}

type DialogLayer = {
  content: HTMLElement
  portal: HTMLElement
}

type LayerManager = {
  isTop: (content: HTMLElement | null) => boolean
  register: (layer: DialogLayer) => () => void
}

const layerManagers = new WeakMap<Document, LayerManager>()

function createLayerManager(document: Document): LayerManager {
  const layers: DialogLayer[] = []
  const originalInertStates = new Map<HTMLElement, InertState>()
  let originalBodyOverflow = ''
  let observer: MutationObserver | null = null

  function restoreElements() {
    for (const [element, state] of originalInertStates) {
      element.inert = state.inert
      if (state.ariaHidden === null) {
        element.removeAttribute('aria-hidden')
      } else {
        element.setAttribute('aria-hidden', state.ariaHidden)
      }
    }
  }

  function hideSiblingsOf(element: HTMLElement) {
    let current: HTMLElement | null = element

    while (current && current !== document.body) {
      const parent: HTMLElement | null = current.parentElement
      if (!parent) break

      for (const sibling of parent.children) {
        if (!(sibling instanceof HTMLElement) || sibling === current) continue

        if (!originalInertStates.has(sibling)) {
          originalInertStates.set(sibling, {
            ariaHidden: sibling.getAttribute('aria-hidden'),
            inert: sibling.inert,
          })
        }
        sibling.inert = true
        sibling.setAttribute('aria-hidden', 'true')
      }

      current = parent
    }
  }

  function syncModalIsolation() {
    restoreElements()

    const topLayer = layers.at(-1)
    if (topLayer) {
      hideSiblingsOf(topLayer.portal)
      document.body.style.overflow = 'hidden'
      return
    }

    originalInertStates.clear()
    document.body.style.overflow = originalBodyOverflow
  }

  return {
    isTop(content) {
      return Boolean(content && layers.at(-1)?.content === content)
    },
    register(layer) {
      if (layers.length === 0) {
        originalBodyOverflow = document.body.style.overflow
        observer = new MutationObserver(syncModalIsolation)
        observer.observe(document.body, { childList: true, subtree: true })
      }

      layers.push(layer)
      syncModalIsolation()

      return () => {
        const index = layers.lastIndexOf(layer)
        if (index !== -1) layers.splice(index, 1)

        if (layers.length === 0) {
          observer?.disconnect()
          observer = null
        }
        syncModalIsolation()
      }
    },
  }
}

function getLayerManager(document: Document) {
  let manager = layerManagers.get(document)
  if (!manager) {
    manager = createLayerManager(document)
    layerManagers.set(document, manager)
  }
  return manager
}

const tabbableSelector = [
  'a[href]',
  'area[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'iframe',
  'object',
  'embed',
  'audio[controls]',
  'video[controls]',
  'summary',
  '[contenteditable="true"]',
  '[tabindex]:not([tabindex="-1"])',
].join(',')

function isTabbable(element: HTMLElement) {
  if (element.hidden || element.closest('[hidden], [inert], [aria-hidden="true"]')) return false

  const styles = element.ownerDocument.defaultView?.getComputedStyle(element)
  return (
    styles?.display !== 'none' &&
    styles?.visibility !== 'hidden' &&
    element.getClientRects().length > 0
  )
}

function getTabbableElements(container: HTMLElement) {
  return Array.from(container.querySelectorAll<HTMLElement>(tabbableSelector)).filter(isTabbable)
}

function focusFirst(container: HTMLElement, preferred?: HTMLElement | null) {
  const target =
    preferred && container.contains(preferred) && !preferred.closest('[inert]')
      ? preferred
      : getTabbableElements(container)[0] ?? container
  target.focus({ preventScroll: true })
  return target
}

export function DialogRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open: controlledOpen,
}: DialogRootProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const [titleRegistrations, setTitleRegistrations] = useState<
    Array<{ id: string; token: symbol }>
  >([])
  const [descriptionRegistrations, setDescriptionRegistrations] = useState<
    Array<{ id: string; token: symbol }>
  >([])
  const generatedId = useId()
  const contentRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const open = controlledOpen ?? uncontrolledOpen

  const requestOpenChange = useCallback(
    (nextOpen: boolean, reason: DialogOpenChangeReason, originalEvent?: Event) => {
      if (nextOpen === open) return
      if (controlledOpen === undefined) setUncontrolledOpen(nextOpen)
      onOpenChange?.(nextOpen, { originalEvent, reason })
    },
    [controlledOpen, onOpenChange, open],
  )

  const registerTitle = useCallback((id: string) => {
    const token = Symbol('dialog-title')
    setTitleRegistrations((registrations) => [...registrations, { id, token }])
    return () =>
      setTitleRegistrations((registrations) =>
        registrations.filter((registration) => registration.token !== token),
      )
  }, [])

  const registerDescription = useCallback((id: string) => {
    const token = Symbol('dialog-description')
    setDescriptionRegistrations((registrations) => [...registrations, { id, token }])
    return () =>
      setDescriptionRegistrations((registrations) =>
        registrations.filter((registration) => registration.token !== token),
      )
  }, [])

  const value = useMemo<DialogContextValue>(
    () => ({
      contentId: `${generatedId}-content`,
      contentRef,
      descriptionId: `${generatedId}-description`,
      descriptionLabelIds:
        descriptionRegistrations.length > 0
          ? descriptionRegistrations.map(({ id }) => id).join(' ')
          : undefined,
      open,
      registerDescription,
      registerTitle,
      requestOpenChange,
      titleLabelId: titleRegistrations.at(-1)?.id,
      titleId: `${generatedId}-title`,
      triggerRef,
    }),
    [
      descriptionRegistrations,
      generatedId,
      open,
      registerDescription,
      registerTitle,
      requestOpenChange,
      titleRegistrations,
    ],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

export type DialogTriggerProps = ButtonHTMLAttributes<HTMLButtonElement>

export const DialogTrigger = forwardRef<HTMLButtonElement, DialogTriggerProps>(function DialogTrigger(
  { onClick, type = 'button', ...props },
  forwardedRef,
) {
  const context = useDialogContext('DialogTrigger')

  return (
    <button
      {...props}
      aria-controls={context.contentId}
      aria-expanded={context.open}
      aria-haspopup="dialog"
      onClick={(event) => {
        onClick?.(event)
        if (!event.defaultPrevented) {
          context.requestOpenChange(true, 'trigger', event.nativeEvent)
        }
      }}
      ref={(node) => {
        context.triggerRef.current = node
        setRef(forwardedRef, node)
      }}
      type={type}
    />
  )
})

export type DialogPortalProps = {
  children: ReactNode
  container?: HTMLElement | null
}

export function DialogPortal({ children, container }: DialogPortalProps) {
  const context = useDialogContext('DialogPortal')
  const [portalNode, setPortalNode] = useState<HTMLElement | null>(null)

  useEffect(() => {
    if (!context.open) return

    const node = document.createElement('div')
    node.dataset.dialogPortal = ''
    ;(container ?? document.body).append(node)
    setPortalNode(node)

    return () => {
      node.remove()
      setPortalNode(null)
    }
  }, [container, context.open])

  if (!context.open || !portalNode) return null

  return createPortal(
    <PortalContext.Provider value={portalNode}>{children}</PortalContext.Provider>,
    portalNode,
  )
}

export type DialogOverlayProps = HTMLAttributes<HTMLDivElement>

export const DialogOverlay = forwardRef<HTMLDivElement, DialogOverlayProps>(function DialogOverlay(
  { onPointerDown, ...props },
  forwardedRef,
) {
  const context = useDialogContext('DialogOverlay')

  return (
    <div
      {...props}
      onPointerDown={(event) => {
        onPointerDown?.(event)
        if (
          !event.defaultPrevented &&
          event.target === event.currentTarget &&
          getLayerManager(event.currentTarget.ownerDocument).isTop(context.contentRef.current)
        ) {
          context.requestOpenChange(false, 'pointer-outside', event.nativeEvent)
        }
      }}
      ref={forwardedRef}
    />
  )
})

export type DialogContentProps = HTMLAttributes<HTMLDivElement> & {
  initialFocusRef?: RefObject<HTMLElement | null>
  onCloseAutoFocus?: (event: Event) => void
  onEscapeKeyDown?: (event: KeyboardEvent) => void
  onOpenAutoFocus?: (event: Event) => void
}

